  <http://www.wikidata.org/entity/Q159> <http://www.wikidata.org/prop/P122> ?q .
  ?q <http://www.wikidata.org/prop/statement/P122> ?uri .
  FILTER NOT EXISTS { ?q <http://www.wikidata.org/prop/qualifier/P582> ?x }
}

SELECT DISTINCT ?s1
WHERE {
  ?s1  ?p1  <http://www.wikidata.org/entity/Q56008> .
  ?s1  <http://www.wikidata.org/prop/direct/P31>  <http://www.wikidata.org/entity/Q11424> .
  ?s1  <http://www.wikidata.org/prop/direct/P2769> ?o1 .
} order by ?o1 limit 1

SELECT DISTINCT ?s1
WHERE {
  ?s1  <http://www.wikidata.org/prop/direct/P31>  <http://www.wikidata.org/entity/Q11424> .
  ?s1  <http://www.wikidata.org/prop/direct/P161>  <http://www.wikidata.org/entity/Q103894> .
  ?s1 <http://www.wikidata.org/prop/direct/P577> ?o1 .
} order by DESC(?o1)  limit 1
